package com.osrsai;

import com.google.gson.Gson;
import com.google.gson.JsonObject;
import com.google.gson.JsonArray;
import java.io.IOException;
import java.util.LinkedHashMap;
import java.util.Map;
import java.util.concurrent.TimeUnit;
import javax.inject.Inject;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Client;
import net.runelite.api.InventoryID;
import net.runelite.api.Item;
import net.runelite.api.ItemContainer;
import net.runelite.api.InstanceTemplates;
import net.runelite.api.Player;
import net.runelite.api.Skill;
import net.runelite.api.VarPlayer;
import net.runelite.api.Quest;
import net.runelite.api.QuestState;
import net.runelite.api.WorldView;
import net.runelite.api.coords.LocalPoint;
import net.runelite.api.coords.WorldPoint;
import net.runelite.api.gameval.VarPlayerID;
import net.runelite.api.vars.AccountType;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.game.ItemManager;
import javax.swing.SwingUtilities;
import okhttp3.Call;
import okhttp3.Callback;
import okhttp3.MediaType;
import okhttp3.OkHttpClient;
import okhttp3.Request;
import okhttp3.RequestBody;
import okhttp3.Response;
import org.jetbrains.annotations.NotNull;

@Slf4j
public class AiService {
    private static final double LOW_TEMPERATURE = 0.2d;
    private static final int MAX_ITEMS_PER_SECTION = 12;
    private static final int MAX_IN_PROGRESS_QUESTS = 12;
    private static final int MAX_CONTEXT_CHARACTERS = 8000;
    private static final int MAX_RECENT_CONVERSATION_CHARS = 1200;
    @Inject
    private Client client;

    @Inject
    private OsrsAiConfig config;

    @Inject
    private OkHttpClient okHttpClient;

    @Inject
    private Gson gson;

    @Inject
    private ItemManager itemManager;

    @Inject
    private ClientThread clientThread;

    @Inject
    private ConfigManager configManager;

    private final LocationResolver locationResolver = new LocationResolver();

    private static final String GEMINI_API_URL = "https://generativelanguage.googleapis.com/v1beta/models/gemini-2.5-flash:generateContent?key=";
    private static final String OPENAI_API_URL = "https://api.openai.com/v1/chat/completions";
    private static final String CLAUDE_API_URL = "https://api.anthropic.com/v1/messages";
    private static final String GROK_API_URL = "https://api.x.ai/v1/chat/completions";

    public void sendQuestion(String question, OsrsAiPanel panel) {
        String apiKey = config.apiKey();
        if (apiKey == null || apiKey.isEmpty()) {
            panel.addMessage("System", "Please set an API key in the plugin config.");
            return;
        }

        panel.setThinking(true);
        clientThread.invokeLater(() -> {
            String promptContext = buildContext();
            String recentConversation = panel.getRecentConversationContext(question);
            AiProvider provider = config.aiProvider();

            Request request;
            switch (provider) {
                case OPENAI:
                    request = buildOpenAiRequest(OPENAI_API_URL, "gpt-4o", apiKey, config.clientId(), promptContext, recentConversation, question);
                    break;
                case GROK:
                    request = buildOpenAiRequest(GROK_API_URL, "grok-4-1-fast-non-reasoning", apiKey, config.clientId(), promptContext, recentConversation, question);
                    break;
                case CLAUDE:
                    request = buildClaudeRequest(apiKey, promptContext, recentConversation, question);
                    break;
                case GEMINI:
                default:
                    request = buildGeminiRequest(apiKey, promptContext, recentConversation, question);
                    break;
            }

            OkHttpClient aiClient = okHttpClient.newBuilder()
                    .connectTimeout(60, TimeUnit.SECONDS)
                    .readTimeout(60, TimeUnit.SECONDS)
                    .writeTimeout(60, TimeUnit.SECONDS)
                    .build();

            aiClient.newCall(request).enqueue(new Callback() {
                @Override
                public void onFailure(@NotNull Call call, @NotNull IOException e) {
                    log.error("Failed to call AI API", e);
                    SwingUtilities.invokeLater(() -> {
                        panel.setThinking(false);
                        panel.addMessage("System", "Error calling AI. Check logs.");
                    });
                }

                @Override
                public void onResponse(@NotNull Call call, @NotNull Response response) throws IOException {
                    if (!response.isSuccessful()) {
                        assert response.body() != null;
                        log.error("API returned error: {}", response.body().string());
                        SwingUtilities.invokeLater(() -> {
                            panel.setThinking(false);
                            panel.addMessage("System", "AI returned an error code " + response.code());
                        });
                        return;
                    }

                    try {
                        assert response.body() != null;
                        String responseBody = response.body().string();
                        JsonObject root = gson.fromJson(responseBody, JsonObject.class);
                        String aiResponseText = extractResponseText(provider, root);

                        SwingUtilities.invokeLater(() -> {
                            panel.setThinking(false);
                            panel.addMessage("AI", aiResponseText.trim());
                        });
                    } catch (Exception e) {
                        log.error("Failed to parse AI response", e);
                        SwingUtilities.invokeLater(() -> {
                            panel.setThinking(false);
                            panel.addMessage("System", "Failed to parse AI response.");
                        });
                    }
                }
            });
        });
    }

    private Request buildGeminiRequest(String apiKey, String context, String recentConversation, String question) {
        String fullPrompt = buildSystemPrompt(context, recentConversation)
                + "\n\nCURRENT USER QUESTION:\n"
                + question;

        JsonObject messageObj = new JsonObject();
        JsonArray partsArray = new JsonArray();
        JsonObject textObj = new JsonObject();
        textObj.addProperty("text", fullPrompt);
        partsArray.add(textObj);
        messageObj.add("parts", partsArray);

        JsonArray contentsArray = new JsonArray();
        contentsArray.add(messageObj);

        JsonObject bodyObj = new JsonObject();
        bodyObj.add("contents", contentsArray);
        JsonObject generationConfig = new JsonObject();
        generationConfig.addProperty("temperature", LOW_TEMPERATURE);
        bodyObj.add("generationConfig", generationConfig);

        String jsonBody = gson.toJson(bodyObj);
        RequestBody requestBody = RequestBody.create(MediaType.parse("application/json"), jsonBody);

        return new Request.Builder()
                .url(GEMINI_API_URL + apiKey)
                .post(requestBody)
                .build();
    }

    private Request buildOpenAiRequest(String apiUrl, String modelName, String apiKey, String clientId, String context, String recentConversation, String question) {
        JsonObject bodyObj = new JsonObject();
        bodyObj.addProperty("model", modelName);
        bodyObj.addProperty("temperature", LOW_TEMPERATURE);

        JsonArray messages = new JsonArray();
        JsonObject systemMessage = new JsonObject();
        systemMessage.addProperty("role", "system");
        systemMessage.addProperty("content", buildSystemPrompt(context, recentConversation));

        JsonObject userMessage = new JsonObject();
        userMessage.addProperty("role", "user");
        userMessage.addProperty("content", question);

        messages.add(systemMessage);
        messages.add(userMessage);
        bodyObj.add("messages", messages);

        String jsonBody = gson.toJson(bodyObj);
        RequestBody requestBody = RequestBody.create(MediaType.parse("application/json"), jsonBody);

        Request.Builder builder = new Request.Builder()
                .url(apiUrl)
                .header("Authorization", "Bearer " + apiKey)
                .post(requestBody);

        if (clientId != null && !clientId.trim().isEmpty()) {
            builder.header("OpenAI-Organization", clientId);
        }

        return builder.build();
    }

    private Request buildClaudeRequest(String apiKey, String context, String recentConversation, String question) {
        JsonObject bodyObj = new JsonObject();
        bodyObj.addProperty("model", "claude-3-5-sonnet-20240620");
        bodyObj.addProperty("system", buildSystemPrompt(context, recentConversation));
        bodyObj.addProperty("max_tokens", 1024);
        bodyObj.addProperty("temperature", LOW_TEMPERATURE);

        JsonArray messages = new JsonArray();
        JsonObject userMessage = new JsonObject();
        userMessage.addProperty("role", "user");
        userMessage.addProperty("content", question);

        messages.add(userMessage);
        bodyObj.add("messages", messages);

        String jsonBody = gson.toJson(bodyObj);
        RequestBody requestBody = RequestBody.create(MediaType.parse("application/json"), jsonBody);

        return new Request.Builder()
                .url(CLAUDE_API_URL)
                .header("x-api-key", apiKey)
                .header("anthropic-version", "2023-06-01")
                .header("content-type", "application/json")
                .post(requestBody)
                .build();
    }

    private String extractResponseText(AiProvider provider, JsonObject root) {
        switch (provider) {
            case OPENAI:
            case GROK:
                return root.getAsJsonArray("choices")
                        .get(0).getAsJsonObject()
                        .getAsJsonObject("message")
                        .get("content").getAsString();
            case CLAUDE:
                return root.getAsJsonArray("content")
                        .get(0).getAsJsonObject()
                        .get("text").getAsString();
            case GEMINI:
            default:
                return root.getAsJsonArray("candidates")
                        .get(0).getAsJsonObject()
                        .getAsJsonObject("content")
                        .getAsJsonArray("parts")
                        .get(0).getAsJsonObject()
                        .get("text").getAsString();
        }
    }

    @SuppressWarnings("deprecation")
    private String buildContext() {
        if (client.getGameState() != net.runelite.api.GameState.LOGGED_IN) {
            return "Player is not logged in.";
        }

        StringBuilder sb = new StringBuilder();
        sb.append("PLAYER PROFILE:\n");

        Player localPlayer = client.getLocalPlayer();
        if (localPlayer != null) {
            sb.append("Name: ").append(localPlayer.getName()).append("\n");
            sb.append("Combat Level: ").append(localPlayer.getCombatLevel()).append("\n");
        }

        AccountType accountType = client.getAccountType();
        sb.append("Account Type: ").append(describeAccountType(accountType)).append("\n");
        sb.append("Account Guidance: ").append(describeAccountGuidance(accountType)).append("\n");
        sb.append("World: ").append(client.getWorld()).append("\n");
        sb.append("Total Level: ").append(client.getTotalLevel()).append("\n");
        sb.append("Run Energy: ").append(client.getEnergy()).append("%\n");
        sb.append("Weight: ").append(client.getWeight()).append(" kg\n");
        sb.append("Hitpoints: ")
                .append(client.getBoostedSkillLevel(Skill.HITPOINTS))
                .append("/")
                .append(client.getRealSkillLevel(Skill.HITPOINTS))
                .append("\n");
        sb.append("Prayer: ")
                .append(client.getBoostedSkillLevel(Skill.PRAYER))
                .append("/")
                .append(client.getRealSkillLevel(Skill.PRAYER))
                .append("\n");
        sb.append("\nCURRENT LOCATION:\n");
        if (localPlayer != null) {
            WorldPoint wp = localPlayer.getWorldLocation();
            if (wp != null) {
                InstanceTemplates instanceTemplate = getInstanceTemplate(localPlayer, wp);
                boolean inInstance = isInInstance(localPlayer);
                sb.append("Location Name: ").append(locationResolver.describeForAi(wp, inInstance, instanceTemplate)).append("\n");
                sb.append("Coordinates: ").append(wp.getX()).append(", ").append(wp.getY()).append(", Plane ").append(wp.getPlane()).append("\n");
                sb.append("Region ID: ").append(wp.getRegionID()).append("\n");
                sb.append("Instanced Area: ").append(inInstance ? "Yes" : "No").append("\n");
            }
        }
        sb.append("\n");

        appendSkillsContext(sb);
        appendItemsContext(sb, "INVENTORY", config.includeInventory(), client.getItemContainer(InventoryID.INVENTORY));
        appendItemsContext(sb, "EQUIPMENT", config.includeEquipment(), client.getItemContainer(InventoryID.EQUIPMENT));

        sb.append("QUEST PROGRESS:\n");
        int qp = client.getVarpValue(VarPlayerID.QP);
        sb.append("Quest Points: ").append(qp).append("\n");

        if (config.includeQuestStatus()) {
            sb.append("In Progress Quests:\n");
            int count = 0;
            for (Quest quest : Quest.values()) {
                if (quest.getState(client) == QuestState.IN_PROGRESS) {
                    if (count < MAX_IN_PROGRESS_QUESTS) {
                        sb.append("- ").append(quest.getName()).append("\n");
                    }
                    count++;
                }
            }
            if (count == 0) {
                sb.append("None\n");
            } else if (count > MAX_IN_PROGRESS_QUESTS) {
                sb.append("- ... and ").append(count - MAX_IN_PROGRESS_QUESTS).append(" more\n");
            }
        } else {
            sb.append("In Progress Quests: Not shared\n");
        }
        sb.append("\n");

        if (config.includeSlayerTask()) {
            sb.append("SLAYER:\n");
            String taskName = configManager.getRSProfileConfiguration("slayer", "taskName");
            if (taskName == null || taskName.isEmpty()) {
                taskName = configManager.getConfiguration("slayer", "taskName");
            }

            String amount = configManager.getRSProfileConfiguration("slayer", "amount");
            if (amount == null || amount.isEmpty()) {
                amount = configManager.getConfiguration("slayer", "amount");
            }

            if (taskName != null && !taskName.isEmpty() && amount != null) {
                sb.append("Slayer Task: ").append(amount).append(" ").append(taskName).append("\n");
            } else {
                sb.append("Slayer Task: None\n");
            }
        } else {
            sb.append("SLAYER:\n");
            sb.append("Slayer Task: Not shared\n");
        }

        return trimToPromptBudget(sb.toString(), MAX_CONTEXT_CHARACTERS, "...[game context truncated for prompt budget]");
    }

    private void appendSkillsContext(StringBuilder sb)
    {
        sb.append("SKILLS:\n");
        if (!config.includeSkills()) {
            sb.append("Not shared\n\n");
            return;
        }

        for (Skill skill : Skill.values()) {
            if (skill != Skill.OVERALL) {
                sb.append(skill.getName())
                        .append(": ")
                        .append(client.getBoostedSkillLevel(skill))
                        .append("/")
                        .append(client.getRealSkillLevel(skill))
                        .append("\n");
            }
        }
        sb.append("\n");
    }

    private void appendItemsContext(StringBuilder sb, String sectionName, boolean includeSection, ItemContainer container)
    {
        sb.append(sectionName).append(":\n");
        if (!includeSection) {
            sb.append("Not shared\n\n");
            return;
        }

        if (container == null || container.getItems().length == 0) {
            sb.append("None\n\n");
            return;
        }

        Map<String, Long> aggregatedItems = new LinkedHashMap<>();
        for (Item item : container.getItems()) {
            if (item == null || item.getId() <= 0 || item.getQuantity() <= 0) {
                continue;
            }

            String itemName = safeItemName(item.getId());
            aggregatedItems.put(itemName, aggregatedItems.getOrDefault(itemName, 0L) + item.getQuantity());
        }

        if (aggregatedItems.isEmpty()) {
            sb.append("None\n\n");
            return;
        }

        int displayed = 0;
        for (Map.Entry<String, Long> entry : aggregatedItems.entrySet()) {
            if (displayed >= MAX_ITEMS_PER_SECTION) {
                break;
            }
            sb.append("- ").append(entry.getKey()).append(" x").append(entry.getValue()).append("\n");
            displayed++;
        }

        if (aggregatedItems.size() > MAX_ITEMS_PER_SECTION) {
            sb.append("- ... and ").append(aggregatedItems.size() - MAX_ITEMS_PER_SECTION).append(" more item types\n");
        }
        sb.append("\n");
    }

    private String safeItemName(int itemId)
    {
        try {
            String name = itemManager.getItemComposition(itemId).getName();
            if (name == null || name.trim().isEmpty()) {
                return "Item " + itemId;
            }
            return name;
        } catch (Exception ex) {
            return "Item " + itemId;
        }
    }

    static String trimToPromptBudget(String text, int maxChars, String truncationLabel)
    {
        if (maxChars <= 0) {
            return "";
        }

        if (text == null || text.trim().isEmpty()) {
            return "None";
        }

        String safeLabel = (truncationLabel == null || truncationLabel.isEmpty())
                ? "...[truncated]"
                : truncationLabel;

        String normalized = text.trim();
        if (normalized.length() <= maxChars) {
            return normalized;
        }

        if (maxChars <= safeLabel.length()) {
            return safeLabel.substring(0, maxChars);
        }

        int keepLength = maxChars - safeLabel.length() - 1;
        return normalized.substring(0, keepLength) + "\n" + safeLabel;
    }

    static String buildSystemPrompt(String context, String recentConversation)
    {
        String compactConversation = trimToPromptBudget(recentConversation, MAX_RECENT_CONVERSATION_CHARS,
                "...[recent conversation truncated]");

        return "You are an Old School RuneScape assistant inside RuneLite.\n"
                + "Use standard OSRS knowledge, but treat the provided GAME CONTEXT as the source of truth for this player's current state.\n"
                + "\n"
                + "GROUNDING RULES:\n"
                + "1. Never invent stats, quests, items, locations, NPCs, or activities.\n"
                + "2. If the answer depends on missing or uncertain information, say you do not know and explain what is missing.\n"
                + "3. Base player-specific advice on the provided context and mention when you are making a general OSRS recommendation.\n"
                + "4. If the location name is approximate or unknown, say so instead of pretending it is exact.\n"
                + "5. Treat Account Type and Account Guidance as authoritative. For Ironman, UIM, GIM, and HGIM accounts, do not recommend invalid trading, Grand Exchange, or banking options.\n"
                + "6. Respect sections marked Not shared and avoid assuming hidden data.\n"
                + "7. Keep answers practical and concise.\n"
                + "8. Prefer plain text over markdown; avoid markdown headings.\n"
                + "\n"
                + "RECENT CONVERSATION:\n"
                + compactConversation
                + "\n\nGAME CONTEXT:\n"
                + trimToPromptBudget(context, MAX_CONTEXT_CHARACTERS, "...[game context truncated for prompt budget]");
    }

    private boolean isInInstance(Player localPlayer)
    {
        WorldView worldView = localPlayer.getWorldView();
        if (worldView != null)
        {
            return worldView.isInstance();
        }

        return client.getTopLevelWorldView() != null && client.getTopLevelWorldView().isInstance();
    }

    private InstanceTemplates getInstanceTemplate(Player localPlayer, WorldPoint worldPoint)
    {
        WorldView worldView = localPlayer.getWorldView();
        if (worldView == null || !worldView.isInstance())
        {
            return null;
        }

        LocalPoint localPoint = LocalPoint.fromWorld(worldView, worldPoint);
        if (localPoint == null)
        {
            localPoint = localPlayer.getLocalLocation();
        }

        if (localPoint == null)
        {
            return null;
        }

        int[][][] chunks = worldView.getInstanceTemplateChunks();
        if (chunks == null)
        {
            return null;
        }

        int plane = worldPoint.getPlane();
        int chunkX = localPoint.getSceneX() / 8;
        int chunkY = localPoint.getSceneY() / 8;
        if (plane < 0 || plane >= chunks.length
                || chunkX < 0 || chunkX >= chunks[plane].length
                || chunkY < 0 || chunkY >= chunks[plane][chunkX].length)
        {
            return null;
        }

        return InstanceTemplates.findMatch(chunks[plane][chunkX][chunkY]);
    }

    private String describeAccountType(AccountType accountType) {
        if (accountType == null) {
            return "Unknown";
        }

        switch (accountType) {
            case IRONMAN:
                return "Ironman";
            case ULTIMATE_IRONMAN:
                return "Ultimate Ironman (UIM)";
            case HARDCORE_IRONMAN:
                return "Hardcore Ironman (HCIM)";
            case GROUP_IRONMAN:
                return "Group Ironman (GIM)";
            case HARDCORE_GROUP_IRONMAN:
                return "Hardcore Group Ironman (HGIM)";
            case NORMAL:
            default:
                return "Normal";
        }
    }

    private String describeAccountGuidance(AccountType accountType)
    {
        if (accountType == null)
        {
            return "Restrictions unknown. Avoid assuming the player can trade or use external help.";
        }

        switch (accountType)
        {
            case IRONMAN:
                return "Self-sufficient Ironman. No trading with other players and no Grand Exchange.";
            case ULTIMATE_IRONMAN:
                return "Ultimate Ironman (UIM). No trading, no Grand Exchange, and no bank storage.";
            case HARDCORE_IRONMAN:
                return "Hardcore Ironman (HCIM). Same practical restrictions as Ironman; preserve hardcore status when relevant.";
            case GROUP_IRONMAN:
                return "Group Ironman (GIM). Prefer advice that works within the group; do not assume normal trading or unrestricted Grand Exchange access.";
            case HARDCORE_GROUP_IRONMAN:
                return "Hardcore Group Ironman (HGIM). Same group restrictions as GIM; preserve hardcore status when relevant.";
            case NORMAL:
            default:
                return "Standard account. Trading, Grand Exchange, and bank usage are available.";
        }
    }
}

package com.osrsai;

import com.google.gson.Gson;
import com.google.gson.JsonObject;
import com.google.gson.JsonArray;
import java.io.IOException;
import java.util.LinkedHashMap;
import java.util.Map;
import java.util.concurrent.CompletableFuture;
import java.util.concurrent.TimeUnit;
import java.util.regex.Matcher;
import java.util.regex.Pattern;
import okhttp3.HttpUrl;
import javax.inject.Inject;
